/** Process-halt recovery of derived metadata; this is not a host power-loss durability simulation. */
class LmdbRamMetadataCrashTest {

	private static final int HALT_STATUS = 87;

	@TempDir(cleanup = CleanupMode.ON_SUCCESS)
	Path directory;

	@ParameterizedTest
	@EnumSource(Cut.class)
	@Timeout(90)
	void dirtyRecoveryUsesAuthoritativeMembershipAfterProcessHalt(Cut cut) throws Exception {
		Path data = directory.resolve("store");
		Path witness = directory.resolve("witness.txt");
		Path output = directory.resolve("child.log");
		String java = Path.of(System.getProperty("java.home"), "bin", "java").toString();
		String mockitoAgent = "-javaagent:"
				+ Path.of(Mockito.class.getProtectionDomain().getCodeSource().getLocation().toURI());
		Process child = new ProcessBuilder(java, "-ea", "-Xmx128m", "-XX:ActiveProcessorCount=2",
				"-XX:-CreateCoredumpOnCrash", "-XX:ErrorFile=" + directory.resolve("hs_err_pid%p.log"),
				"--enable-native-access=ALL-UNNAMED", mockitoAgent, "-cp", System.getProperty("java.class.path"),
				CrashChild.class.getName(), data.toString(), cut.name(), witness.toString())
						.redirectErrorStream(true)
						.redirectOutput(output.toFile())
						.start();
		try {
			assertTrue(child.waitFor(60, TimeUnit.SECONDS), "child must reach its certified cut: " + output);
			assertThat(child.exitValue()).as(Files.readString(output)).isEqualTo(HALT_STATUS);
			assertThat(Files.readString(witness)).isEqualTo("native-committed=" + cut.name());
		} finally {
			if (child.isAlive()) {
				child.destroyForcibly();
				assertTrue(child.waitFor(10, TimeUnit.SECONDS), "owned child must be reaped");
			}
		}
		try (TripleStore reopened = new TripleStore(data.toFile(), config(), null);
				Txn snapshot = reopened.getTxnManager().createReadTxn()) {
			assertRecovered(reopened, snapshot);
			assertRecoveredNativeBase(snapshot);
		}
		// A second reopen also checks the reconstructed clean base, not only the live recovery view.
		try (TripleStore reopened = new TripleStore(data.toFile(), config(), null);
				Txn snapshot = reopened.getTxnManager().createReadTxn()) {
			assertRecovered(reopened, snapshot);
			assertRecoveredNativeBase(snapshot);
		}
	}

	private static void assertRecoveredNativeBase(Txn snapshot) throws Exception {
		LmdbPersistentAdjacency nativeBase = LmdbPersistentAdjacency.openExisting(snapshot.get());
		assertThat(nativeBase.count(snapshot.get(), true)).isEqualTo(3);
		assertThat(nativeBase.count(snapshot.get(), false)).isEqualTo(2);
		assertThat(nativeBase.contextTotal(snapshot.get(), 50)).isEqualTo(2);
		assertThat(nativeBase.referenceCount(snapshot.get(), 50)).as("four equal roles in each of two planes")
				.isEqualTo(8);
		assertThat(nativeBase.referenceCount(snapshot.get(), 0)).isZero();
	}

	private static void assertRecovered(TripleStore store, Txn snapshot) throws Exception {
		assertThat(store.countTriples(snapshot, -1, -1, -1, -1, true)).isEqualTo(3);
		assertThat(store.countTriples(snapshot, -1, -1, -1, -1, false)).isEqualTo(2);
		assertThat(store.countTriples(snapshot, 10, 20, 30, 7, true)).as("deleted quad stays deleted").isZero();
		assertThat(store.countTriples(snapshot, 50, 50, 50, 50, true)).isEqualTo(1);
		assertThat(store.countTriples(snapshot, 50, 50, 50, 50, false)).isEqualTo(1);
		assertThat(scan(store, snapshot, true)).containsExactlyInAnyOrder(
				List.of(11L, 21L, 31L, 9L), List.of(13L, 23L, 33L, 11L), List.of(50L, 50L, 50L, 50L));
		assertThat(scan(store, snapshot, false)).containsExactlyInAnyOrder(
				List.of(12L, 22L, 32L, 0L), List.of(50L, 50L, 50L, 50L));
		List<Long> contexts = new ArrayList<>();
		try (LmdbContextIdIterator iterator = store.getContexts(snapshot)) {
			for (long[] context; (context = iterator.next()) != null;) {
				contexts.add(context[0]);
			}
		}
		assertThat(contexts).containsExactly(0L, 9L, 11L, 50L);
		List<Long> candidates = new ArrayList<>(List.of(0L, 7L, 10L, 20L, 30L, 50L, 11L, 21L, 31L, 9L, 99L));
		store.filterUsedIdsBounded(candidates);
		assertThat(candidates).containsExactly(0L, 7L, 10L, 20L, 30L, 99L);
	}

	private static List<List<Long>> scan(TripleStore store, Txn snapshot, boolean explicit) throws Exception {
		List<List<Long>> result = new ArrayList<>();
		try (RecordIterator iterator = store.getTriples(snapshot, -1, -1, -1, -1, explicit)) {
			for (long[] quad; (quad = iterator.next()) != null;) {
				result.add(List.of(quad[0], quad[1], quad[2], quad[3]));
			}
		}
		return result;
	}

	private static LmdbStoreConfig config() {
		return new LmdbStoreConfig().setForceSync(true).setAutoGrow(false).setTripleDBSize(16L << 20);
	}

	private enum Cut {
		AFTER_NATIVE_COMMIT,
		AFTER_COMMIT_RETURN,
		AFTER_PARTIAL_CHECKPOINT
	}

	public static final class CrashChild {
		public static void main(String[] args) throws Exception {
			Path directory = Path.of(args[0]);
			Files.createDirectories(directory);
			Cut cut = Cut.valueOf(args[1]);
			Path witness = Path.of(args[2]);
			try (TripleStore store = new TripleStore(directory.toFile(), config(), null)) {
				store.startTransaction();
				store.storeTriple(10, 20, 30, 7, true);
				store.storeTriple(50, 50, 50, 50, true);
				store.storeTriple(50, 50, 50, 50, false);
				// Persist pages so the following removal creates an actual absent delta, not merely
				// cancellation of an unmerged positive delta. Compaction preserves logical metadata.
				LmdbPersistentAdjacency.openExisting(store.writeTxn).compact(store.writeTxn, true);
				store.commit();
				store.startTransaction();
				store.removeTriplesByContext(10, 20, 30, 7, true, ignored -> {
				});
				store.storeTriple(11, 21, 31, 9, true);
				store.commit();
				// Establish a checkpoint base containing the removal and both role-sharing quads.
				// Two later commits create separate 12-entry and 13-entry absolute metadata segments.
				store.checkpointMetadata(4096);
				store.startTransaction();
				store.storeTriple(12, 22, 32, 0, false);
				store.commit();
				store.startTransaction();
				long writer = store.writeTxn;
				int metadata = LmdbPersistentAdjacency.openExisting(writer).metadataDbi();
				store.storeTriple(13, 23, 33, 11, true);
				if (cut == Cut.AFTER_NATIVE_COMMIT) {
					try (MockedStatic<LMDB> calls = mockStatic(LMDB.class, invocation -> {
						if (invocation.getMethod().getName().equals("mdb_txn_commit")
								&& (long) invocation.getArgument(0) == writer) {
							assertThat(rawExplicitTotal(writer, metadata)).as("checkpoint is still deferred")
									.isLessThan(3);
							int result = (int) invocation.callRealMethod();
							assertThat(result).isEqualTo(MDB_SUCCESS);
							halt(cut, witness);
							return result;
						}
						return invocation.callRealMethod();
					})) {
						store.commit();
					}
				} else {
					store.commit();
					if (cut == Cut.AFTER_PARTIAL_CHECKPOINT) {
						assertThat(store.metadataCheckpoint().pendingSegments()).isEqualTo(2);
						assertThat(store.checkpointMetadata(12)).isEqualTo(12);
						assertThat(store.metadataCheckpoint().pendingSegments()).isEqualTo(1);
					}
					try (Txn snapshot = store.getTxnManager().createReadTxn()) {
						assertThat(rawExplicitTotal(snapshot.get(), metadata)).as("checkpoint is still deferred")
								.isLessThan(3);
						assertRecovered(store, snapshot);
					}
					halt(cut, witness);
				}
				throw new AssertionError("certified halt was not reached");
			}
		}

		private static void halt(Cut cut, Path witness) throws Exception {
			Files.writeString(witness, "native-committed=" + cut.name());
			Runtime.getRuntime().halt(HALT_STATUS);
		}
	}

	private static long rawExplicitTotal(long txn, int metadata) {
		try (MemoryStack stack = MemoryStack.stackPush()) {
			MDBVal key = MDBVal.malloc(stack).mv_data(stack.bytes((byte) 1, (byte) 0));
			MDBVal value = MDBVal.malloc(stack);
			int result = mdb_get(txn, metadata, key, value);
			if (result == MDB_NOTFOUND) {
				return 0;
			}
			assertThat(result).isEqualTo(MDB_SUCCESS);
			return value.mv_data().order(ByteOrder.BIG_ENDIAN).getLong();
		}
	}
}
